/**
 * Preview documents for the code panel.
 *
 * Threat model (see docs/architecture/code-export-system.md): generated
 * output is untrusted content — it embeds design-authored text and may
 * contain markup-like strings. Previews therefore render inside an iframe
 * with `sandbox=""` (opaque origin, no scripts, no same-origin access, no
 * forms, no popups, no top navigation) and `srcDoc` content only: no
 * network URLs are fetched beyond what the generated file itself inlines
 * (data URLs), and the preview never receives document data beyond the
 * generated bytes.
 */

/** Targets whose actual output a browser can render without a runtime. */
export type PreviewableTarget = 'svg' | 'html';

export function isPreviewableTarget(target: string): target is PreviewableTarget {
  return target === 'svg' || target === 'html';
}

/**
 * Compose the exact generated output into a standalone document. This is
 * the deliverable's own bytes — the preview never applies editor-side CSS
 * patches or substitutes assets.
 */
export function buildPreviewSrcDoc(
  kind: PreviewableTarget,
  output: { html: string; css?: string },
): string {
  if (kind === 'svg') return output.html;
  return [
    '<!doctype html>',
    '<html><head><meta charset="utf-8">',
    output.css ? `<style>${output.css}</style>` : '',
    '</head><body>',
    output.html,
    '</body></html>',
  ].join('');
}
